import{_ as t,c as o,o as a,ae as i}from"./chunks/framework.ixH79I-5.js";const s="/BetterKMR/docs/assets/2025-04-30_19-03.CnT3tEXp.png",n="/BetterKMR/docs/assets/2025-04-30_19-10.keaNXa6n.png",r="/BetterKMR/docs/assets/2025-04-30_19-18.ymVyMYru.png",l="/BetterKMR/docs/assets/2025-04-30_19-24.DjGakOhx.png",d="/BetterKMR/docs/assets/2025-04-30_19-29.BNs4__4j.png",f=JSON.parse('{"title":"🔧 How to Test New Builds","description":"To test new builds when we release them, you need to use a GitHub account to download the builds. Every time we commit to the repository, GitHub actions automatically build them.","frontmatter":{"title":"🔧 How to Test New Builds","description":"To test new builds when we release them, you need to use a GitHub account to download the builds. Every time we commit to the repository, GitHub actions automatically build them."},"headers":[],"relativePath":"develop/how_to_test_new_builds.md","filePath":"develop/how_to_test_new_builds.md"}'),h={name:"develop/how_to_test_new_builds.md"};function u(c,e,b,p,m,g){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="🔧-how-to-test-new-builds" tabindex="-1">🔧 How to Test New Builds <a class="header-anchor" href="#🔧-how-to-test-new-builds" aria-label="Permalink to &quot;🔧 How to Test New Builds&quot;">​</a></h1><p style="color:#ff0000;">⚠️ NOTE: Intended for InterLabs staff, administrators, and testers only.</p><p style="color:rgb(121, 121, 121);">ℹ️ <span style="font-style:italic;">This guide only provides the necessary information for Chrome even though Firefox is mentioned. Please request for help if you are having trouble replicating this on Firefox.</span></p><h3 id="getting-the-build-archive-file" tabindex="-1">Getting the Build Archive File <a class="header-anchor" href="#getting-the-build-archive-file" aria-label="Permalink to &quot;Getting the Build Archive File&quot;">​</a></h3><p>To test new builds when we release them, you need to use a GitHub account to download the builds.</p><p>However, as a tester, you must let us know of your account so we can add you to the organisation, so that you can download the builds for either (or both) Chrome and Firefox.</p><p>Once you have been added to the organisation, head over to the repository <a href="https://github.com/Interlabs-Official/BetterKMR" target="_blank" rel="noreferrer">here</a> and click &quot;Actions&quot; to view the latest workflow builds.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+s+'" alt="Part 1 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>The GitHub Actions page, where builds get automatically made from newest to oldest.</em></td></tr></tbody></table><p>Click on the latest build. For this one, we&#39;ll be clicking on <a href="https://github.com/Interlabs-Official/BetterKMR/actions/runs/14747362102" target="_blank" rel="noreferrer">Better Settings Look + Code Clean + Redeem Codes #47</a> because at the time of writing this, this is the latest build.</p><p>If asked to test a specific build, you may be given a build number (e.g. #47) or a commit tag (e.g. a2ca09d) which you can find easily on that page.</p><p style="color:rgb(121, 121, 121);">ℹ️ <span style="font-style:italic;">Builds get automatically made when a new commit is pushed to main.</span></p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+n+'" alt="Part 2 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>The build page, where we can download the latest build for either Chrome or Firefox.</em></td></tr></tbody></table><p>When on the page, there should be a download button next to &quot;extension-chrome&quot; (or &quot;extension-firefox&quot;) in the artifacts section. Click on it to get a .zip archive containing the extension.</p><h3 id="enabling-the-extension-on-chrome" tabindex="-1">Enabling the Extension on Chrome <a class="header-anchor" href="#enabling-the-extension-on-chrome" aria-label="Permalink to &quot;Enabling the Extension on Chrome&quot;">​</a></h3><p style="color:rgb(121, 121, 121);">ℹ️ <span style="font-style:italic;">This also works for Chromium-based browsers like Brave and Arc.</span></p><p>The browser that I&#39;m using is Brave, but the steps are likely similar or exactly the same depending on the browser you&#39;re using.</p><p>First of all, unzip the build file you downloaded so that it is contained in a folder (using tools like Windows&#39; default archive manager, 7-Zip, etc). Then, go to your browser and type what is shown below:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+r+'" alt="Part 3 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>In your browser&#39;s URL bar, type chrome://extensions and press Enter.</em></td></tr></tbody></table><p>On the Extensions page, there should be a &quot;Developer mode&quot; toggle switch. Turn it on, then click &quot;Load unpacked&quot; and find the folder that was the result of unzipping the build file, and click &quot;Select&quot; or &quot;Choose&quot; (or whatever it is on your device).</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+l+'" alt="Part 4 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>Note: You do <strong>not</strong> need the &quot;GNOME Shell Integration&quot; extension, this is something specific for my device.</em></td></tr></tbody></table><p>If all goes well and is successful, you should get a notification like this below:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+d+'" alt="Part 5 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>Note: Even if the notification doesn&#39;t appear, it should still be installed on your browser.</em></td></tr></tbody></table><p>If you&#39;re having trouble, please feel free to let any of the staff know to help assist you.<br> Happy testing! 🎉</p>',23)]))}const w=t(h,[["render",u]]);export{f as __pageData,w as default};
